/* 修正 No.55 (2026-04-24): 予約投稿機能 - ルーム内の予約投稿一覧パネル
   バナーをクリックすると開き、各アイテムの 編集 / 削除 を操作できる。 */
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  Output,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ScheduledMessage } from '../../../../shared/services/scheduled-messages.service';

@Component({
  selector: 'app-scheduled-list',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './scheduled-list.component.html',
  styleUrls: ['./scheduled-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScheduledListComponent {
  @Input() items: ScheduledMessage[] = [];
  @Output() edit = new EventEmitter<ScheduledMessage>();
  @Output() delete = new EventEmitter<ScheduledMessage>();
  @Output() close = new EventEmitter<void>();

  trackById(_i: number, item: ScheduledMessage): string {
    return item.id;
  }

  formatTime(ts: number): string {
    const d = new Date(ts);
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hh = String(d.getHours()).padStart(2, '0');
    const mm = String(d.getMinutes()).padStart(2, '0');
    return `${y}/${m}/${day} ${hh}:${mm}`;
  }

  preview(text: string): string {
    const t = (text || '').trim();
    if (t.length <= 80) return t;
    return t.slice(0, 80) + '…';
  }

  onEdit(item: ScheduledMessage, ev: Event): void {
    ev.stopPropagation();
    this.edit.emit(item);
  }

  onDelete(item: ScheduledMessage, ev: Event): void {
    ev.stopPropagation();
    this.delete.emit(item);
  }

  onClose(): void {
    this.close.emit();
  }
}
