/* 修正 No.55 (2026-04-24): 予約投稿機能 - スケジュール指定モーダル
   MatDialog で開き、日付/時刻入力・クイックプリセット・プレビュー・バリデーション付き。
   ConfirmDialogComponent と同じ panelClass / backdrop / カラーで統一。 */
import {
  ChangeDetectionStrategy,
  Component,
  HostListener,
  Inject,
  OnInit,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';

export interface ScheduleSendModalData {
  /** モーダルを開いた時点のメッセージ本文 (プレビュー表示用) */
  messageText: string;
  /** 既存の予約を編集する場合は初期日時を渡す */
  initialScheduledAt?: number;
  /** モードラベル (新規 = "予約する" / 編集 = "更新する") */
  mode?: 'create' | 'edit';
}

export interface ScheduleSendModalResult {
  scheduledAt: number;
}

@Component({
  selector: 'app-schedule-send-modal',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './schedule-send-modal.component.html',
  styleUrls: ['./schedule-send-modal.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScheduleSendModalComponent implements OnInit {
  dateValue = '';
  timeValue = '';
  errorMessage = '';

  constructor(
    @Inject(MAT_DIALOG_DATA) public data: ScheduleSendModalData,
    private dialogRef: MatDialogRef<
      ScheduleSendModalComponent,
      ScheduleSendModalResult | null
    >,
  ) {}

  ngOnInit(): void {
    const initial = this.data?.initialScheduledAt
      ? new Date(this.data.initialScheduledAt)
      : this.defaultDateTime();
    this.dateValue = this.toDateInput(initial);
    this.timeValue = this.toTimeInput(initial);
  }

  get isEdit(): boolean {
    return this.data?.mode === 'edit';
  }

  get title(): string {
    return '予約投稿';
  }

  get confirmText(): string {
    return this.isEdit ? '更新する' : '予約する';
  }

  get previewText(): string {
    return (this.data?.messageText || '').trim() || '(本文なし)';
  }

  /** デフォルト = 現在時刻 + 1 時間 */
  private defaultDateTime(): Date {
    const d = new Date();
    d.setHours(d.getHours() + 1);
    d.setSeconds(0, 0);
    return d;
  }

  private toDateInput(d: Date): string {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }

  private toTimeInput(d: Date): string {
    const h = String(d.getHours()).padStart(2, '0');
    const mi = String(d.getMinutes()).padStart(2, '0');
    return `${h}:${mi}`;
  }

  applyPreset(preset: 'in1h' | 'tomorrow9' | 'nextMon9'): void {
    const d = new Date();
    if (preset === 'in1h') {
      d.setHours(d.getHours() + 1);
      d.setSeconds(0, 0);
    } else if (preset === 'tomorrow9') {
      d.setDate(d.getDate() + 1);
      d.setHours(9, 0, 0, 0);
    } else if (preset === 'nextMon9') {
      // 現在曜日から次の月曜まで。月曜(1)-日曜(0)。
      const day = d.getDay();
      // (1 - day + 7) % 7 が 0 になる = 今日が月曜なので翌週月曜にする
      let add = (1 - day + 7) % 7;
      if (add === 0) add = 7;
      d.setDate(d.getDate() + add);
      d.setHours(9, 0, 0, 0);
    }
    this.dateValue = this.toDateInput(d);
    this.timeValue = this.toTimeInput(d);
    this.errorMessage = '';
  }

  private parseScheduledAt(): number | null {
    if (!this.dateValue || !this.timeValue) return null;
    const [y, m, day] = this.dateValue.split('-').map(Number);
    const [h, mi] = this.timeValue.split(':').map(Number);
    if (
      !Number.isFinite(y) ||
      !Number.isFinite(m) ||
      !Number.isFinite(day) ||
      !Number.isFinite(h) ||
      !Number.isFinite(mi)
    ) {
      return null;
    }
    const d = new Date(y, m - 1, day, h, mi, 0, 0);
    return d.getTime();
  }

  onDateTimeChange(): void {
    this.errorMessage = '';
  }

  onConfirm(): void {
    const t = this.parseScheduledAt();
    if (t == null) {
      this.errorMessage = '日付と時刻を入力してください';
      return;
    }
    if (t - Date.now() < 60 * 1000) {
      this.errorMessage = '現在より1分以上あとの日時を指定してください';
      return;
    }
    this.dialogRef.close({ scheduledAt: t });
  }

  onCancel(): void {
    this.dialogRef.close(null);
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    this.onCancel();
  }
}
