  /* 修正 No.47 (2026-04-24): 同一ミリ秒内での投稿順を担保するため、
     静的シーケンスを Date.now() の後ろに付与する。sort key の /(\d{10,})/
     正規表現は先頭の Date.now 数列だけを抽出するため後続の seq は無視されるが、
     id 比較時には seq 付き文字列で一意性が保たれ、重複排除も崩れない。 */
  private static _seq = 0;
  private nextMsgId(prefix = 'm'): string {
    return prefix + Date.now() + '-' + (++ChatPageComponent._seq).toString(36);
  }

  /* 修正 No.50 (2026-04-24): 投稿時の日付ラベルを実クロックに合わせる
     (以前は seed messages が "2026年X月Y日" にハードコードされていたため、
      新規投稿が「時刻だけ・日付なし」で表示されて「日付がズレている」と見えていた) */
  private todayDateLabel(d: Date = new Date()): string {
    return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
  }

  /** 指定ルーム内の最後のメッセージの dateLabel を算出 (無ければ空文字) */
  private lastDateLabelForRoom(roomId: string): string {
    const roomMsgs = this.messages.filter(m => m.roomId === roomId);
    for (let i = roomMsgs.length - 1; i >= 0; i--) {
      if (roomMsgs[i].dateLabel) return roomMsgs[i].dateLabel as string;
    }
    return '';
  }

  @ViewChild('messagesScrollRef') messagesScrollRef?: ElementRef<HTMLDivElement>;
  /** メイン入力 textarea の ViewChild 参照 (送信後の DOM 直接リセット用 — ユーザー指示 2026-04-21) */
  @ViewChild('msgInputRef') msgInputRef?: ElementRef<HTMLTextAreaElement>;
  private pendingScrollToBottom = false;
  private lastScrolledRoomId = '';
  /**
   * プログラム的スクロール中はユーザー操作由来のスクロール検知を抑制する。
   * Date.now() がこの値を超えるまでスクロールハンドラは何もしない。
   * これが無いと auto-scroll-to-bottom を「ユーザーの下スクロール」と誤検知して
   * 入力エリアが --hidden にされてしまう致命バグが発生する。
   */
  private suppressScrollUntilMs = 0;

  ngAfterViewChecked(): void {
    if (this.pendingScrollToBottom) {
      const isMobileView = typeof window !== 'undefined' && window.innerWidth <= 768;
      // 自動スクロール中はユーザー由来スクロール検知を抑制 (400ms)
      // これが無いと "scroll down" と誤判定されて入力欄が hidden になる
      this.suppressScrollUntilMs = Date.now() + 400;

      if (isMobileView) {
        try {
          window.scrollTo({
            top: document.documentElement.scrollHeight,
            left: 0,
            behavior: 'auto',
          });
        } catch { /* fallback */ }
      } else if (this.messagesScrollRef) {
        const el = this.messagesScrollRef.nativeElement;
        el.scrollTop = el.scrollHeight;
      }
      this.pendingScrollToBottom = false;
      // 自動スクロール直後は入力欄を強制表示 + ヘッダー/ナビも表示
      document.querySelector('.chat-room__input')?.classList.remove('chat-room__input--hidden');
      document.querySelector('.header')?.classList.remove('header--hidden');
      document.querySelector('.chat-room')?.classList.remove('chat-room--scroll-collapsed');
      document.querySelector('.nav-bottom')?.classList.remove('nav-bottom--hidden');
      this.headerHidden = false;
    }
  }

  private scheduleScrollToBottom(): void {
    this.pendingScrollToBottom = true;
  }

  /**
   * 投稿直後などに、確実に最新メッセージを画面下に表示させるための強制スクロール。
   * 複数フレーム待ってから scrollHeight を計測し直し、画像/添付などのレイアウト
   * 確定後の位置まで追従する。
   * (ユーザー指示 2026-04-21: 投稿しても最新ポストが一番下に表示されない対策)
   */
  private forceScrollToBottom(attempts = 5): void {
    const isMobileView = typeof window !== 'undefined' && window.innerWidth <= 768;
    this.suppressScrollUntilMs = Date.now() + 800;
    const doScroll = () => {
      if (isMobileView) {
        try {
          window.scrollTo({
            top: document.documentElement.scrollHeight,
            left: 0,
            behavior: 'auto',
          });
          // 直近の msg (最後のメッセージ要素) が最下部に見えるよう
          // scrollIntoView でも保険をかける。キーボード表示中で
          // documentElement の scrollHeight が伸び縮みしても確実に下端に来る。
          /* fix (2026-04-27): 旧セレクタ '.msg-wrap' は現行 template に存在せず
             scrollIntoView fallback が死んでいた。実体クラス '.msg-bubble' に変更。 */
          const msgs = document.querySelectorAll('.msg-bubble');
          const last = msgs[msgs.length - 1] as HTMLElement | undefined;
          if (last && typeof last.scrollIntoView === 'function') {
            last.scrollIntoView({ block: 'end', behavior: 'auto' });
          }
        } catch { /* noop */ }
      } else if (this.messagesScrollRef) {
        const el = this.messagesScrollRef.nativeElement;
        el.scrollTop = el.scrollHeight;
      }
      // 入力欄とヘッダー/ナビを強制表示 (誤判定防止)
      document.querySelector('.chat-room__input')?.classList.remove('chat-room__input--hidden');
      document.querySelector('.header')?.classList.remove('header--hidden');
      document.querySelector('.chat-room')?.classList.remove('chat-room--scroll-collapsed');
      document.querySelector('.nav-bottom')?.classList.remove('nav-bottom--hidden');
      this.headerHidden = false;
    };
    const run = (remaining: number) => {
      doScroll();
      if (remaining > 0 && typeof requestAnimationFrame !== 'undefined') {
        requestAnimationFrame(() => run(remaining - 1));
      }
    };
    if (typeof requestAnimationFrame !== 'undefined') {
      requestAnimationFrame(() => run(attempts));
    } else {
      setTimeout(() => run(attempts), 0);
    }
    // キーボード表示中は visualViewport の再配置が少し遅れるため
    // 100ms / 300ms でもう一度下端へ寄せ直す
    setTimeout(doScroll, 100);
    setTimeout(doScroll, 300);
  }

