  /** 汎用スレッド生成: 任意のroomIdに対して100件の双方向会話を生成 */
  private static generateThreadMessages(
    roomId: string,
    idPrefix: string,
    senders: { name: string; initial: string; color: string; isMe?: boolean }[],
    texts: string[],
    dayOffset: number,
  ): ChatMessage[] {
    const messages: ChatMessage[] = [];
    const now = new Date('2026-04-10T10:00:00');
    const startTime = now.getTime() - (7 + dayOffset) * 24 * 60 * 60 * 1000;
    let lastDateLabel = '';
    // 決定論的な疑似乱数（Mulberry32）で roomId ベースのシードを使用
    let seed = 0;
    for (let i = 0; i < roomId.length; i++) seed = (seed * 31 + roomId.charCodeAt(i)) >>> 0;
    const rand = () => {
      seed = (seed + 0x6D2B79F5) >>> 0;
      let t = seed;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    for (let i = 0; i < 100; i++) {
      const t = startTime + (i / 100) * (7 * 24 * 60 * 60 * 1000) + (rand() * 600000);
      const d = new Date(t);
      const hh = d.getHours().toString().padStart(2, '0');
      const mm = d.getMinutes().toString().padStart(2, '0');
      /* 修正 No.50 (2026-04-24): 年を実クロックに合わせる (投稿日時が「ズレて見える」のを防ぐ) */
      const dateLabel = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
      // 交互 + ランダム要素で会話感を出す
      const senderIdx = senders.length === 2
        ? (i % 2 === 0 ? 1 : 0) // 直接チャットは相手→自分の交互
        : (rand() < 0.3 ? 0 : 1 + Math.floor(rand() * (senders.length - 1)));
      const sender = senders[senderIdx];
      const text = texts[i % texts.length];
      /* 修正 No.58 (2026-04-25): シードメッセージ ID に実タイムスタンプを埋め込む
         これにより getMessageSortKey の /(\d{10,})/ regex がシードの本来の時刻を拾い、
         ユーザーの新規投稿 (Date.now() ms の ID) が常にシードより後に並ぶようになる。
         (以前は dateLabel 未設定のメッセージが「今日」+ HH:MM で sort されてしまい、
         新規投稿の間にシードが割り込む誤並びが発生していた) */
      const msg: ChatMessage = {
        id: `${idPrefix}-${Math.floor(t)}-${i + 1}`,
        roomId,
        senderName: sender.name,
        senderInitial: sender.initial,
        senderColor: sender.color,
        text,
        time: `${hh}:${mm}`,
        isMe: !!sender.isMe,
      };
      if (dateLabel !== lastDateLabel) {
        msg.dateLabel = dateLabel;
        lastDateLabel = dateLabel;
      }
      if (i % 17 === 0) {
        msg.reactions = [{ emoji: '👍', count: 1 + (i % 3), mine: i % 2 === 0 }];
      }
      messages.push(msg);
    }
    return messages;
  }

