  /** ブラウザバック対応: popstate で戻る動作を制御 */
  @HostListener('window:popstate')
  onPopState(): void {
    if (!this.isMobile) return;
    // モーダルが開いていれば閉じる（優先度順）
    if (this.showMessageMenu) { this.showMessageMenu = false; this.cdr.markForCheck(); return; }
    if (this.showAvatarCropModal) { this.showAvatarCropModal = false; this.cdr.markForCheck(); return; }
    if (this.showNewChatModal || this.showMemberListModal || this.showAddMemberModal ||
        this.showBookmarksModal || this.showTagsModal || this.showMediaModal ||
        this.showAiModal || this.showAttachModal || this.showTaskCreateModal ||
        this.showTaskListModal || this.showLightbox || this.showMediaCarousel ||
        this.showScheduleModal || this.showFolderCreateModal || this.showFolderRenameModal ||
        this.showFolderAddToModal || this.showEmojiPopup) {
      this.closeAllModals();
      this.cdr.markForCheck();
      return;
    }
    /* fix B7 (2026-04-28): 詳細パネルが開いていてサブビュー (members 経由の
       leave-confirm/block-confirm 等) にいる場合は、まず members → menu に
       階層的に戻してから初めてパネル全閉する。ブラウザーバックで
       「ひとつ前の画面」に戻る期待値に揃える。 */
    if (this.showDetailPanel && this.rightPanelView !== 'menu') {
      if (this.rightPanelView === 'leave-confirm' || this.rightPanelView === 'block-confirm') {
        this.rightPanelView = 'members';
      } else {
        this.rightPanelView = 'menu';
      }
      this.cdr.markForCheck();
      return;
    }
    if (this.showDetailPanel) { this.showDetailPanel = false; this.cdr.markForCheck(); return; }
    // ルームが開いていればリストに戻る
    if (this.mobilePane === 'room') {
      this.mobilePane = 'list';
      this.selectedRoomId = '';
      this.cdr.markForCheck();
      return;
    }
  }

