  // ====== Folders ======
  openFolderCreateModal(): void {
    this.newFolderName = '';
    this.newFolderParentId = null;
    this.newFolderUseParent = false;
    this.showFolderCreateModal = true;
  }

  createFolder(): void {
    const name = this.newFolderName.trim();
    if (!name) return;
    const id = 'folder-' + Date.now();
    this.folders = [
      ...this.folders,
      { id, name, icon: 'folder', parentId: this.newFolderUseParent ? (this.newFolderParentId || undefined) : undefined },
    ];
    this.showFolderCreateModal = false;
    /* fix Sheet#57/#60 (2026-04-27): 新規フォルダ永続化 */
    this.persistFolders();
    this.showToast(`フォルダ「${name}」を作成しました`);
  }

  renameFolder(folder: Folder): void {
    this.folderRenameTarget = folder;
    this.folderRenameInput = folder.name;
    this.showFolderRenameModal = true;
  }

  confirmRenameFolder(): void {
    const next = this.folderRenameInput.trim();
    if (!next || !this.folderRenameTarget) return;
    const id = this.folderRenameTarget.id;
    this.folders = this.folders.map(f => f.id === id ? { ...f, name: next } : f);
    this.showFolderRenameModal = false;
    this.folderRenameTarget = null;
    this.folderRenameInput = '';
    /* fix Sheet#57 (2026-04-27): フォルダ名変更も永続化 */
    this.persistFolders();
    this.showToast('フォルダ名を変更しました');
  }

  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async deleteFolder(folder: Folder): Promise<void> {
    if (folder.system) {
      this.showToast('システムフォルダは削除できません');
      return;
    }
    const count = this.getRoomsInFolder(folder.id).length;
    if (count > 0) {
      this.showToast('空のフォルダのみ削除できます');
      return;
    }
    const ok = await this.confirmDialog.confirm({
      title: 'フォルダの削除',
      message: `フォルダ「${folder.name}」を削除しますか？`,
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.folders = this.folders.filter(f => f.id !== folder.id);
    /* fix Sheet#57 (2026-04-27): フォルダ削除も永続化 */
    this.persistFolders();
    this.showToast('フォルダを削除しました');
  }

