  /** 修正 No.40 (2026-04-24): 直前にハイライトした要素。再ジャンプ時の上書き用 */
  private lastHighlightedEl: HTMLElement | null = null;
  jumpToSearchResult(msg: ChatMessage): void {
    // モバイルでは右パネル（検索パネル）を閉じてからスクロール
    if (this.isMobile) {
      this.showDetailPanel = false;
    }
    // messageSearchQueryが有効の場合はフィルタを解除してからスクロール
    const hadFilter = !!this.messageSearchQuery.trim();
    if (hadFilter) {
      this.messageSearchQuery = '';
    }
    // 連続ジャンプ時は前のハイライトを即クリア
    if (this.lastHighlightedEl) {
      this.lastHighlightedEl.classList.remove('msg-highlight');
      this.lastHighlightedEl = null;
    }
    // DOM描画を待ってからスクロール
    setTimeout(() => {
      const el = document.getElementById('msg-' + msg.id);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        // 修正 No.40 (2026-04-24): ジャンプ先メッセージを3秒間はっきりハイライト
        // 同じ要素に再度クラスを付けても animation が再生されるよう一度リフローを挟む
        el.classList.remove('msg-highlight');
        void el.offsetWidth;
        el.classList.add('msg-highlight');
        this.lastHighlightedEl = el;
        setTimeout(() => {
          if (this.lastHighlightedEl === el) {
            el.classList.remove('msg-highlight');
            this.lastHighlightedEl = null;
          }
        }, 3000);
      }
    }, hadFilter || this.isMobile ? 200 : 50);
  }
  highlightSearchText(text: string): string {
    if (!text) return '';
    const q = this.threadSearchQuery.trim();
    if (!q) return text;
    const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const esc = (s: string) => s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'} as Record<string,string>)[c]);

    // テキストを行で分割し、マッチ行の前後2行を含めたスニペットを作る
    const lines = text.split('\n');
    const re = new RegExp(escaped, 'gi');
    const matchLineIndices = new Set<number>();
    lines.forEach((line, i) => { if (re.test(line)) matchLineIndices.add(i); });

    if (matchLineIndices.size === 0) {
      // マッチなし（部分文字列が行をまたぐケース） — テキスト先頭80文字
      const snippet = text.length > 80 ? text.slice(0, 80) + '…' : text;
      return esc(snippet).replace(new RegExp(escaped, 'gi'), m => `<strong class="search-highlight">${m}</strong>`);
    }

    // マッチ行の前後2行を含める
    const contextLines = 2;
    const includeLines = new Set<number>();
    matchLineIndices.forEach(i => {
      for (let j = Math.max(0, i - contextLines); j <= Math.min(lines.length - 1, i + contextLines); j++) {
        includeLines.add(j);
      }
    });

    const sortedIndices = [...includeLines].sort((a, b) => a - b);
    const snippetParts: string[] = [];
    let prevIdx = -2;
    for (const idx of sortedIndices) {
      if (idx > prevIdx + 1 && prevIdx >= 0) snippetParts.push('…');
      snippetParts.push(lines[idx]);
      prevIdx = idx;
    }
    // 先頭・末尾が省略されている場合
    if (sortedIndices[0] > 0) snippetParts.unshift('…');
    if (sortedIndices[sortedIndices.length - 1] < lines.length - 1) snippetParts.push('…');

    const snippet = snippetParts.join('\n');
    const safeSnippet = esc(snippet);
    return safeSnippet.replace(new RegExp(escaped, 'gi'), m => `<strong class="search-highlight">${m}</strong>`).replace(/\n/g, '<br>');
  }

