  // ====== AI modal ======
  openAiModal(): void {
    this.aiResult = '';
    this.aiSuggestions = [];

    if (this.replyToMessage) {
      // 返信/引用モード: 返信先のメッセージに対する返答候補を生成
      this.aiMode = 'reply';
      this.aiPrompt = this.replyToMessage.text || '';
      this.showAiModal = true;
      this.generateAi();
    } else if (this.messageInput.trim().length > 0) {
      // 改善モード: 入力中のテキストを改善
      this.aiMode = 'improve';
      this.aiPrompt = this.messageInput;
      this.showAiModal = true;
      this.generateAi();
    } else {
      // テンプレートモード: 従来のテンプレート選択
      this.aiMode = 'template';
      this.aiTemplate = 'greeting';
      this.aiPrompt = this.quickAiTemplates[0].prompt;
      this.showAiModal = true;
    }
  }

  selectAiTemplate(id: string): void {
    const t = this.quickAiTemplates.find(t => t.id === id);
    if (t) {
      this.aiTemplate = id;
      this.aiPrompt = t.prompt;
    }
  }

  generateAi(): void {
    this.aiLoading = true;
    this.aiResult = '';
    this.aiSuggestions = [];

    if (this.aiMode === 'reply') {
      // 返信候補を3つ生成
      const replyText = this.aiPrompt;
      this._callGeminiForSuggestions(
        `あなたはビジネスチャットのアシスタントです。以下のメッセージに対する適切な返信候補を3つ生成してください。` +
        `それぞれ異なるトーン（丁寧・カジュアル・簡潔）で作成してください。` +
        `各候補は「---」で区切ってください。候補以外のテキストは含めないでください。\n\nメッセージ: ${replyText}`
      );
    } else if (this.aiMode === 'improve') {
      // 文章改善候補を3つ生成
      const draft = this.aiPrompt;
      this._callGeminiForSuggestions(
        `あなたはビジネスチャットの文章改善アシスタントです。以下の下書きテキストを、より伝わりやすく、わかりやすく、補足の効いた文章に改善してください。` +
        `3つの異なる改善案を提示してください（丁寧版・簡潔版・詳細版）。` +
        `各候補は「---」で区切ってください。候補以外のテキストは含めないでください。\n\n下書き: ${draft}`
      );
    } else {
      // テンプレートモード: モック生成（従来の動作）
      setTimeout(() => {
        const samples: Record<string, string> = {
          greeting: 'お世話になっております。\n石澤です。\n本日もよろしくお願いいたします。',
          schedule: 'お世話になっております。\n来週の打ち合わせの件でご連絡いたしました。\n以下の候補日でご都合いかがでしょうか。\n・3/15 (月) 14:00-\n・3/16 (火) 10:00-\n・3/17 (水) 15:00-',
          followup: 'お世話になっております。\n先日の商談はありがとうございました。\nその後、ご検討状況はいかがでしょうか。\nご不明点などございましたらお気軽にお問い合わせください。',
          thanks: 'お世話になっております。\n本日はお忙しい中、お時間をいただきまして誠にありがとうございました。\n引き続き、よろしくお願いいたします。',
          apology: 'お世話になっております。\nこの度は、スケジュール変更のご連絡となり大変申し訳ございません。\n代替日程について別途ご相談させてください。',
        };
        this.aiSuggestions = [samples[this.aiTemplate] || 'メッセージを生成しました。'];
        this.aiLoading = false;
        this.cdr.markForCheck();
      }, 600);
    }
  }

  private _callGeminiForSuggestions(prompt: string): void {
    const apiKey = 'AIzaSyAFJ0sI1LjhaTSVCCZ3XQnXuZ5TJDnPiKE';
    const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
    fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
    })
      .then(r => r.json())
      .then(data => {
        const text = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
        // 「---」で分割して候補リストにする
        this.aiSuggestions = text.split(/---+/).map((s: string) => s.trim()).filter((s: string) => s.length > 0);
        if (this.aiSuggestions.length === 0) {
          this.aiSuggestions = [text.trim() || '生成に失敗しました。もう一度お試しください。'];
        }
        this.aiLoading = false;
        this.cdr.markForCheck();
      })
      .catch(() => {
        this.aiSuggestions = ['AI生成に失敗しました。ネットワーク接続を確認してください。'];
        this.aiLoading = false;
        this.cdr.markForCheck();
      });
  }

