/* 修正 No.55 (2026-04-24): 予約投稿機能
   ユーザーがメッセージを「指定した未来の日時に送信する」ために、
   予約メッセージを localStorage に永続化し、時間経過で自動送信する。
   - getForRoom$() で購読 → バナー / 一覧パネルをリアクティブに更新
   - dueMessage$ を ChatPageComponent が購読 → 到達したメッセージを
     既存 registerExternalMessage フローに流す (通常送信と同じ表示・永続化)
*/
import { Injectable, OnDestroy } from '@angular/core';
import { BehaviorSubject, Observable, Subject } from 'rxjs';
import { map } from 'rxjs/operators';

export interface ScheduledMessage {
  id: string;
  roomId: string;
  text: string;
  scheduledAt: number;   // unix ms
  createdAt: number;     // unix ms
  senderName: string;
  attachments?: any[];
  replyTo?: string;
  tags?: string[];
}

const STORAGE_KEY = 'schecon.scheduledMessages.v1';
const TICK_INTERVAL_MS = 30 * 1000; // 30秒に1回スキャン

@Injectable({ providedIn: 'root' })
export class ScheduledMessagesService implements OnDestroy {
  private scheduled$ = new BehaviorSubject<ScheduledMessage[]>(this.load());
  private due$ = new Subject<ScheduledMessage>();
  private intervalId: any = null;
  /** 起動時にまとめて発火された予約投稿数 (トースト用) */
  private catchUpCount = 0;
  private catchUpEmitted$ = new Subject<number>();

  constructor() {
    // 起動時に期限切れの予約投稿をまとめて発火 (オフライン中に通過した分)
    this.catchUpOverdue();
    // 定期的なスキャン開始
    if (typeof window !== 'undefined') {
      this.intervalId = setInterval(() => this.tick(), TICK_INTERVAL_MS);
    }
  }

  ngOnDestroy(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  // ========== Public API ==========

  /** すべての予約投稿 */
  getAll(): ScheduledMessage[] {
    return this.scheduled$.value;
  }

  /** 指定ルームの予約投稿 (同期) */
  getForRoom(roomId: string): ScheduledMessage[] {
    return this.scheduled$.value
      .filter(m => m.roomId === roomId)
      .sort((a, b) => a.scheduledAt - b.scheduledAt);
  }

  /** 指定ルームの予約投稿 (Observable) */
  getForRoom$(roomId: string): Observable<ScheduledMessage[]> {
    return this.scheduled$.asObservable().pipe(
      map(list =>
        list
          .filter(m => m.roomId === roomId)
          .sort((a, b) => a.scheduledAt - b.scheduledAt),
      ),
    );
  }

  /** 期限到達メッセージ (ChatPage が購読して実送信) */
  dueMessage$(): Observable<ScheduledMessage> {
    return this.due$.asObservable();
  }

  /** 起動時キャッチアップで送信された合計件数を通知 */
  catchUpCount$(): Observable<number> {
    return this.catchUpEmitted$.asObservable();
  }

  /** 予約投稿を追加 */
  schedule(msg: Omit<ScheduledMessage, 'id' | 'createdAt'>): ScheduledMessage {
    const entry: ScheduledMessage = {
      ...msg,
      id: 'sched-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      createdAt: Date.now(),
    };
    const next = [...this.scheduled$.value, entry];
    this.scheduled$.next(next);
    this.save(next);
    return entry;
  }

  /** 予約投稿を部分更新 (編集時) */
  update(id: string, patch: Partial<ScheduledMessage>): void {
    const next = this.scheduled$.value.map(m =>
      m.id === id ? { ...m, ...patch } : m,
    );
    this.scheduled$.next(next);
    this.save(next);
  }

  /** 予約投稿をキャンセル (削除) */
  cancel(id: string): void {
    const next = this.scheduled$.value.filter(m => m.id !== id);
    this.scheduled$.next(next);
    this.save(next);
  }

  // ========== Internal ==========

  /** 起動時に期限切れの予約投稿をまとめて due として発火 */
  private catchUpOverdue(): void {
    const now = Date.now();
    const due = this.scheduled$.value.filter(m => m.scheduledAt <= now);
    if (due.length === 0) return;
    const remaining = this.scheduled$.value.filter(m => m.scheduledAt > now);
    this.scheduled$.next(remaining);
    this.save(remaining);
    // サブスクライバー登録までの猶予を設ける (micro tick 後に emit)
    setTimeout(() => {
      due.forEach(m => this.due$.next(m));
      this.catchUpCount = due.length;
      this.catchUpEmitted$.next(due.length);
    }, 0);
  }

  /** 定期的に期限チェック */
  private tick(): void {
    const now = Date.now();
    const list = this.scheduled$.value;
    const due = list.filter(m => m.scheduledAt <= now);
    if (due.length === 0) return;
    const remaining = list.filter(m => m.scheduledAt > now);
    this.scheduled$.next(remaining);
    this.save(remaining);
    due.forEach(m => this.due$.next(m));
  }

  // ========== localStorage ==========

  private load(): ScheduledMessage[] {
    if (typeof window === 'undefined' || !window.localStorage) return [];
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const arr = JSON.parse(raw);
      return Array.isArray(arr) ? arr : [];
    } catch {
      return [];
    }
  }

  private save(list: ScheduledMessage[]): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
    } catch {
      /* quota/serialize error ignored */
    }
  }
}
